create table public.discovery_sources (id uuid primary key default gen_random_uuid(), name text not null, base_url text not null check(base_url ~ '^https://'), source_type text not null default 'html_calendar' check(source_type in ('html_calendar','organizer_page')), active boolean not null default true, region text not null default 'Sul de Minas', last_checked_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(base_url));
create table public.discovered_events (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.discovery_sources on delete cascade, source_url text not null, external_id text, name text not null, event_date timestamptz, city text, state text, organizer_name text, registration_url text, cover_image_url text, raw_title text, status text not null default 'pending' check(status in ('pending','imported','ignored','duplicate','error')), duplicate_event_id uuid references public.events on delete set null, discovered_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by uuid references auth.users on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(source_id,source_url), unique(source_id,external_id));
create table public.discovery_runs(id uuid primary key default gen_random_uuid(), started_at timestamptz not null default now(), finished_at timestamptz, status text not null default 'running' check(status in ('running','completed','partial','failed')), source_count int not null default 0, discovered_count int not null default 0, new_count int not null default 0, duplicate_count int not null default 0, error_count int not null default 0, error_details jsonb not null default '[]'::jsonb, triggered_by uuid references auth.users on delete set null);
alter table public.discovery_sources enable row level security; alter table public.discovered_events enable row level security; alter table public.discovery_runs enable row level security;
create policy discovery_sources_admin on public.discovery_sources for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy discovered_events_admin on public.discovered_events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy discovery_runs_admin on public.discovery_runs for all to authenticated using(public.is_admin()) with check(public.is_admin());
grant select,insert,update,delete on public.discovery_sources,public.discovered_events,public.discovery_runs to authenticated;
